        if (v < curMin) curMin = v;   // 维护前缀最小
        preMax[i] = curMax;
        preMin[i] = curMin;
    }

    long long maxSum = 0, minSum = 0;
    // r 依次为 n-1, n-3, ...
    for (int r = n - 1; r >= 1; r -= 2) {
        maxSum += preMax[r];
        minSum += preMin[r];
    }
    return {maxSum, minSum};
}

